class LIS3DH_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16

    def __init__(self):
        self.regs = {}
        self._initialize_registers()

    def _initialize_registers(self):
        # Initialize all registers to their reset values
        for reg in self.device['registers']:
            addr = reg['addr']
            if reg['access'] == 'RW':
                self.regs[addr] = reg['reset']
            elif reg['access'] == 'RO':
                self.regs[addr] = reg['reset']
            else:
                raise ValueError(f"Unsupported register access type {reg['access']}")

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise KeyError(f"Unknown register address: {addr}")

        # Read the entire register if nbytes > 1, otherwise read only the relevant bytes
        if nbytes == 1:
            if 'single_byte_semantics' in reg and reg['single_byte_semantics'] == True:
                return (self.regs[addr] >> 8) & 0xFF  # Return bits 15:8
            else:
                return self.regs[addr]
        else:
            return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise KeyError(f"Unknown register address: {addr}")

        # Only update the relevant bytes if nbytes > 1
        if nbytes == 1:
            if 'single_byte_semantics' in reg and reg['single_byte_semantics'] == True:
                self.regs[addr] = (self.regs[addr] & 0xFF) | ((data << 8) & 0xFF)
            else:
                self.regs[addr] = data
        else:
            self.regs[addr] = data

